# Source this in every terminal:  source env.sh
# It sets the SLIM endpoint, the certificates, DID authentication and the
# member DIDs for this example.

CONCORD_EXAMPLE="$(cd "$(dirname "${BASH_SOURCE[0]:-$0}")" && pwd)"
export CONCORD_EXAMPLE
CONCORD_ROOT="$(cd "$CONCORD_EXAMPLE/../.." && pwd)"

export SLIM_ENDPOINT="${SLIM_ENDPOINT:-127.0.0.1:47560}"

# Where agentbridge looks for the certificates and the CA generated by setup.sh.
export SHADI_TMP_DIR="$CONCORD_EXAMPLE/.tmp"
export SLIM_TLS_CERT="$SHADI_TMP_DIR/shadi-slim-mtls/client-avatar.crt"
export SLIM_TLS_KEY="$SHADI_TMP_DIR/shadi-slim-mtls/client-avatar.key"

# DID authentication. Each agent's DID is derived from this seed and its id, so
# the member list below is fixed for this seed. It is a demo seed: do not use
# it for anything real.
export SHADI_SLIM_AUTH=did
export SLIM_HUMAN_SEED="shadi-demo-human-root-secret"
# coordinator, microservices, monolith, pragmatist
export SLIM_MEMBER_DIDS="did:key:z6MkhehSzV3KaYw7h1BJf9DwgfHwE8gQx9LUydQC7i4UnQMo,did:key:z6Mkmmqomz8xEiVYyVAEPSYkaH4saH5rPA7fqZrrTkhfqCDA,did:key:z6MkskLR2pT4aKJFUyY8EKxCpaQ4Za2euspCoTG226pAQi9s,did:key:z6MkmZXU1eXCRPXn26uGA34kc1rKetYTZaMn5kuZQmGA5mnM"

# The tools. A build of this repository is used when there is one.
if [[ -z "${AGENTBRIDGE:-}" ]]; then
  if [[ -x "$CONCORD_ROOT/target/debug/agentbridge" ]]; then
    AGENTBRIDGE="$CONCORD_ROOT/target/debug/agentbridge"
  else
    AGENTBRIDGE=agentbridge
  fi
fi
if [[ -z "${SHADICTL:-}" ]]; then
  if [[ -x "$CONCORD_ROOT/target/debug/shadictl" ]]; then
    SHADICTL="$CONCORD_ROOT/target/debug/shadictl"
  else
    SHADICTL=shadictl
  fi
fi
export AGENTBRIDGE SHADICTL

export PATH="$CONCORD_EXAMPLE/bin:$PATH"
